-- Исходная выгрузка из Excel «Т-Путешествия» за период 2026-01-01 … 2026-10-31.
-- Файл выдаётся готовым: не редактируйте его.

CREATE TABLE raw_flights (
    flight_no TEXT,
    airline_name TEXT,
    departure_at TIMESTAMP,
    arrival_at TIMESTAMP,
    from_iata TEXT,
    from_airport TEXT,
    from_city TEXT,
    from_country TEXT,
    to_iata TEXT,
    to_airport TEXT,
    to_city TEXT,
    to_country TEXT,
    base_price NUMERIC(10,2)
);


CREATE TABLE raw_hotels (
    hotel_name TEXT,
    stars INT,
    city TEXT,
    country TEXT,
    price_per_night NUMERIC(10,2)
);


CREATE TABLE raw_flight_orders (
    order_number TEXT,
    order_created_at TIMESTAMP,
    order_status TEXT,
    user_email TEXT,
    user_full_name TEXT,
    user_phone_main TEXT,
    user_phone_extra TEXT,
    passenger_full_name TEXT,
    passenger_birth_date DATE,
    passenger_passport TEXT,
    flight_no TEXT,
    airline_name TEXT,
    departure_at TIMESTAMP,
    arrival_at TIMESTAMP,
    from_iata TEXT,
    from_airport TEXT,
    from_city TEXT,
    from_country TEXT,
    to_iata TEXT,
    to_airport TEXT,
    to_city TEXT,
    to_country TEXT,
    base_price NUMERIC(10,2),
    ticket_class TEXT,
    ticket_price NUMERIC(10,2),
    payment_id TEXT,
    payment_method TEXT,
    paid_at TIMESTAMP,
    payment_amount NUMERIC(10,2)
);


CREATE TABLE raw_hotel_orders (
    order_number TEXT,
    order_created_at TIMESTAMP,
    order_status TEXT,
    user_email TEXT,
    user_full_name TEXT,
    user_phone_main TEXT,
    user_phone_extra TEXT,
    hotel_name TEXT,
    hotel_stars INT,
    hotel_city TEXT,
    hotel_country TEXT,
    price_per_night NUMERIC(10,2),
    check_in DATE,
    check_out DATE,
    guests INT,
    payment_id TEXT,
    payment_method TEXT,
    paid_at TIMESTAMP,
    payment_amount NUMERIC(10,2)
);


CREATE TABLE raw_reviews (
    user_email TEXT,
    user_full_name TEXT,
    hotel_name TEXT,
    hotel_city TEXT,
    rating INT,
    review_text TEXT,
    reviewed_at TIMESTAMP
);

